async (page) => {
  await page.evaluate(() => {
    window.productEvent = 'Parkland Shooting';
    window.productClaim = 'Hoax Proof';
    window.productStatus = 'in stock';
    window.productPrice = '45.99';
  });
  return "Global variables created successfully";
}

async (page) => {
  await page.waitForSelector('input[name="product[name]"]', { state: 'visible', timeout: 15000 });
  const event = await page.evaluate(() => window.productEvent);
  const claim = await page.evaluate(() => window.productClaim);
  const price = await page.evaluate(() => window.productPrice);
  await page.fill('input[name="product[name]"]', event + ' ' + claim);
  await page.fill('input[name="product[price]"]', price);
  await page.click('#save-button');
  return "Form populated and submitted successfully";
}
